/**
 * The table rises and falls with where the exam lands in the review cycle (a word reviewed the day before the
 * exam scores higher than one reviewed a week before). Read raw, that would make introducing a word earlier
 * look worse. The projection uses the lower envelope instead — for each d the lowest value at d or later —
 * which never decreases with d and never overstates.
 */
const ENVELOPE: readonly number[] = P_NEW.map((_, d) => (d === 0 ? 0 : Math.min(...P_NEW.slice(d))))

/** Expected recall on the exam of a word introduced `days` days before it (beyond the table: its last value). */
export const pNew = (days: number) => (days <= 0 ? 0 : ENVELOPE[Math.min(days, ENVELOPE.length - 1)])
